import heapq

def stable_toposort(graph):
    nodes = list(graph.keys())
    if not nodes:
        return []

    index_map = {node: i for i, node in enumerate(nodes)}
    indegree = {node: 0 for node in nodes}
    dependents = {node: [] for node in nodes}

    # Compute indegree and check for missing dependencies
    for node, deps in graph.items():
        for dep in deps:
            if dep not in index_map:
                raise ValueError(f"Missing dependency: {dep}")
            indegree[node] += 1
            dependents[dep].append(node)

    # Min-heap of (original_index, node) for ready nodes
    heap = []
    for node in nodes:
        if indegree[node] == 0:
            heapq.heappush(heap, (index_map[node], node))

    result = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, (index_map[dependent], dependent))

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
