        """Return all dotted leaf paths under this schema dict."""
        paths = []
        for key, value in schema.items():
            new_prefix = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                paths.extend(get_leaf_paths(value, new_prefix))
            else:
                paths.append(new_prefix)
        return paths

    result = []

    def rec(exp, act, path):
        # Both must be dicts at this point (top level or nested object)
        for key in sorted(set(exp.keys()) | set(act.keys())):
            new_path = f"{path}.{key}" if path else key
            if key not in exp:
                # Extra field in actual
                if isinstance(act[key], dict):
                    result.extend(get_leaf_paths(act[key], new_path))
                else:
                    result.append(new_path)
            elif key not in act:
                # Missing field from actual
                if isinstance(exp[key], dict):
                    result.extend(get_leaf_paths(exp[key], new_path))
                else:
                    result.append(new_path)
            else:
                exp_val = exp[key]
                act_val = act[key]
                if isinstance(exp_val, dict) and isinstance(act_val, dict):
                    rec(exp_val, act_val, new_path)
                elif exp_val != act_val:
                    # Type mismatch (string vs string different, or dict vs string)
                    result.append(new_path)

    rec(expected, actual, "")
    return sorted(set(result))
